"use client"

import {
  createContext,
  startTransition,
  use,
  useEffect,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import {
  defineChart,
  type ChartPoint,
  type ChartValue,
  type StaticChartDefinition,
} from "@tanstack/charts"
import { motion } from "@tanstack/charts/motion"
import {
  RendererChart as ChartPrimitive,
  type ChartProps as TanStackChartProps,
} from "@tanstack/charts/react/tooltip"
import { svgChartRenderer } from "@tanstack/charts/svg/renderer"
import { tooltip as tooltipExtension } from "@tanstack/charts/tooltip"
import { twMerge } from "cn"
import {
  ToggleButton,
  ToggleButtonGroup,
} from "react-aria-components/ToggleButtonGroup"

import {
  CHART_HIT_MARK_ID,
  defaultValueFormatter,
  getChartColors,
  getLabel,
  getTextLabel,
  type ChartColorPalette,
  type ChartConfig,
  type ChartLegendProps,
  type ChartSizeProps,
  type ChartTooltipContentProps,
  type ChartTooltipProps,
  type ChartTooltipRenderer,
  type TooltipDatum,
} from "./chart-core"

const ENTRANCE_DURATION = 900

// Marks grow from their baseline on mount. The entrance also replays over
// server-rendered SVG, which is hidden until the chart has measured its container.
const entranceRenderer = motion({
  initial: "always",
  transition: {
    type: "tween",
    duration: ENTRANCE_DURATION,
    easing: "ease-out",
  },
})

type ChartFrameContextValue = {
  colors?: ChartColorPalette
  config: ChartConfig
  selectedSeries: string | null
  selectSeries: (series: string | null) => void
}

const ChartFrameContext = createContext<ChartFrameContextValue | null>(null)

function useChartFrame() {
  const context = use(ChartFrameContext)
  if (!context) {
    throw new Error("Chart components must be rendered inside <ChartFrame>")
  }
  return context
}

/** Series highlighted from the legend or by selecting a mark. */
function useSeriesSelection() {
  const [selectedSeries, setSelectedSeries] = useState<string | null>(null)

  const selectSeries = (series: string | null) => {
    startTransition(() => {
      setSelectedSeries(series)
    })
  }

  return [selectedSeries, selectSeries] as const
}

type ChartProps<
  TDatum extends TooltipDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = Pick<
  TanStackChartProps<TDatum, TXValue, TYValue>,
  "className" | "style"
> & {
  ariaLabel: string
  config: ChartConfig
  /** Height used when `size` sets neither `height` nor `aspectRatio`. */
  defaultHeight?: number
  definition: StaticChartDefinition<TDatum, TXValue, TYValue, "dom">
  /**
   * How marks appear on mount: `grow` from their baseline, or `reveal` left to
   * right. Marks that reveal should opt out of `grow` with
   * `motion: revealEntranceMotion`.
   */
  entrance?: "grow" | "reveal"
  onSelect?: (point: ChartPoint<TDatum, TXValue, TYValue> | null) => void
  size?: ChartSizeProps
  tooltip?: ChartTooltipRenderer<TDatum, TXValue, TYValue> | false
  tooltipProps?: ChartTooltipProps
  valueFormatter?: (value: number) => string
}

function Chart<
  TDatum extends TooltipDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>({
  ariaLabel,
  className,
  config,
  defaultHeight = 288,
  definition,
  entrance = "grow",
  onSelect,
  size,
  style,
  tooltip,
  tooltipProps,
  valueFormatter = defaultValueFormatter,
}: ChartProps<TDatum, TXValue, TYValue>) {
  // Hide the first paint until the chart matches its container width, so the
  // server-rendered `initialWidth` layout never flashes.
  const [ready, setReady] = useState(false)
  // After the entrance, paint with the plain SVG renderer. The motion renderer turns every hover state change
  // into a scene animation that the next pointer move cancels before its first frame, so hover highlights
  // only appeared once the pointer stopped.
  const [entered, setEntered] = useState(false)
  useEffect(() => {
    if (!ready) {
      return
    }
    const timeout = window.setTimeout(
      () => setEntered(true),
      ENTRANCE_DURATION + 100
    )
    return () => window.clearTimeout(timeout)
  }, [ready])
  const hasTooltip = tooltip !== false
  let height = size?.height
  if (height === undefined && size?.aspectRatio === undefined) {
    height = defaultHeight
  }

  return (
    <ChartPrimitive
      ariaLabel={ariaLabel}
      aspectRatio={size?.aspectRatio}
      className={twMerge(
        "min-w-0 text-xs text-muted-foreground [&_svg.ts-chart]:outline-none",
        ready ? "opacity-100" : "opacity-0",
        className
      )}
      definition={
        hasTooltip
          ? defineChart(definition, {
              tooltip: {
                anchor: tooltipProps?.anchor,
                offset: tooltipProps?.offset,
                placement: tooltipProps?.placement,
                // Follow the pointer immediately; the renderer's tween made the tooltip trail and wobble between points.
                motion: false,
                // A click already selects a series, so it should not also pin.
                sticky: onSelect === undefined,
                use: tooltipExtension,
              },
            })
          : definition
      }
      height={height}
      initialWidth={size?.initialWidth ?? 720}
      onRender={(context) => {
        if (ready) {
          return
        }

        const measuredWidth = context.container.getBoundingClientRect().width
        if (
          measuredWidth > 0 &&
          Math.abs(context.scene.width - measuredWidth) < 1
        ) {
          if (entrance === "reveal") {
            revealMarks(context.container)
          }
          setReady(true)
        }
      }}
      onSelect={onSelect}
      renderer={entered ? svgChartRenderer : entranceRenderer}
      renderTooltipBody={
        hasTooltip
          ? ({ points, primaryPoint }) => {
              const contentProps = {
                activeSeries: primaryPoint?.datum.series,
                config,
                points: uniqueSeriesPoints(points),
                tooltipProps,
                valueFormatter,
              }

              return tooltip ? (
                tooltip(contentProps)
              ) : (
                <ChartTooltipContent {...contentProps} />
              )
            }
          : undefined
      }
      style={style}
    />
  )
}

/** Wipes the marks layer in from the left, leaving axes and grid in place. */
function revealMarks(container: HTMLElement) {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    return
  }

  // The negative insets keep strokes at the plot edges from being clipped.
  container
    .querySelector(".ts-chart__marks")
    ?.animate(
      [
        { clipPath: "inset(-8% 100% -8% -8%)" },
        { clipPath: "inset(-8% -8% -8% -8%)" },
      ],
      { duration: 900, easing: "cubic-bezier(0.25, 0.1, 0.25, 1)" }
    )
}

/** Keeps one tooltip row per series when several marks share a datum. */
function uniqueSeriesPoints<
  TPoint extends { datum: { series: string }; markId: string },
>(points: readonly TPoint[]) {
  const seen = new Set<string>()
  // Hit-target marks share the datum but not the series color, so the visible mark's point wins.
  const ordered = [...points].sort(
    (a, b) =>
      Number(a.markId === CHART_HIT_MARK_ID) -
      Number(b.markId === CHART_HIT_MARK_ID)
  )
  return ordered.filter((point) => {
    if (seen.has(point.datum.series)) {
      return false
    }
    seen.add(point.datum.series)
    return true
  })
}

type ChartFrameProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  children: ReactNode
  colors?: ChartColorPalette
  config: ChartConfig
  legend?: ReactNode | false
  onSelectedSeriesChange: (series: string | null) => void
  selectedSeries: string | null
}

function ChartFrame({
  children,
  className,
  colors,
  config,
  legend = <ChartLegend />,
  onSelectedSeriesChange,
  selectedSeries,
  ...props
}: ChartFrameProps) {
  return (
    <ChartFrameContext
      value={{
        colors,
        config,
        selectedSeries,
        selectSeries: onSelectedSeriesChange,
      }}
    >
      <div
        {...props}
        className={twMerge("z-20 flex w-full min-w-0 flex-col", className)}
      >
        {children}
        {legend}
      </div>
    </ChartFrameContext>
  )
}

function ChartLegend({
  align = "center",
  className,
  hideIcon = false,
  verticalAlign = "bottom",
  ...props
}: ChartLegendProps) {
  const { colors, config, selectedSeries, selectSeries } = useChartFrame()
  const chartColors = getChartColors(config, colors)
  let justifyClass = "justify-center"
  if (align === "left") {
    justifyClass = "justify-start"
  } else if (align === "right") {
    justifyClass = "justify-end"
  }

  return (
    <ToggleButtonGroup
      aria-label="Chart series"
      className={twMerge(
        "flex flex-wrap items-center gap-1",
        verticalAlign === "top" ? "order-first pb-2" : "order-last pt-2",
        justifyClass,
        className
      )}
      onSelectionChange={(keys) => {
        selectSeries([...keys][0]?.toString() ?? null)
      }}
      selectedKeys={selectedSeries ? [selectedSeries] : []}
      selectionMode="single"
      {...props}
    >
      {Object.entries(config).map(([series, item]) => {
        const Icon = item.icon
        return (
          <ToggleButton
            aria-label={`${getTextLabel(config, series)} series`}
            className={twMerge(
              "relative flex min-h-10 items-center gap-2 rounded-full px-3 py-1.5 text-xs font-medium text-muted-foreground outline-none",
              "transition-[background-color,color,opacity,scale,box-shadow] duration-150 ease-out",
              "hover:bg-muted/70 hover:text-foreground selected:bg-muted selected:text-foreground selected:shadow-[inset_0_0_0_1px_color-mix(in_srgb,var(--border)_80%,transparent)]",
              "focus-visible:ring-2 focus-visible:ring-ring/40 active:scale-[0.96]"
            )}
            id={series}
            key={series}
          >
            {Icon && !hideIcon ? (
              <Icon data-slot="icon" />
            ) : (
              <span
                aria-hidden
                className="size-2 shrink-0 rounded-full shadow-[0_0_0_1px_color-mix(in_srgb,currentColor_10%,transparent)]"
                style={{ backgroundColor: chartColors[series] }}
              />
            )}
            {item.label ?? series}
          </ToggleButton>
        )
      })}
    </ToggleButtonGroup>
  )
}

function ChartTooltipContent<
  TDatum extends TooltipDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>({
  config,
  points,
  tooltipProps,
  valueFormatter,
}: ChartTooltipContentProps<TDatum, TXValue, TYValue>) {
  const seriesColors = getChartColors(config)
  const seriesOrder = Object.keys(config)
  const {
    className,
    hideIndicator = false,
    hideLabel = false,
    hint,
    indicator = "dot",
    labelFormatter,
    labelSeparator = true,
  } = tooltipProps ?? {}
  const firstPoint = points[0]

  if (!firstPoint) {
    return null
  }

  const rawLabel = String(firstPoint.datum.category)
  const hintContent = hint?.(rawLabel)

  return (
    <div
      className={twMerge(
        "grid min-w-36 items-start text-xs text-current",
        className
      )}
    >
      {hideLabel ? null : (
        <span className="font-semibold text-foreground">
          {labelFormatter ? labelFormatter(rawLabel) : rawLabel}
        </span>
      )}
      {hideLabel || !labelSeparator ? null : (
        <span
          aria-hidden
          className="mt-2 mb-2.5 block h-px w-full bg-border/70"
        />
      )}
      <div className="grid gap-2.5">
        {[...points]
          // Same order as the legend.
          .sort(
            (a, b) =>
              seriesOrder.indexOf(a.datum.series) -
              seriesOrder.indexOf(b.datum.series)
          )
          .map((point) => {
            const { series, value } = point.datum
            if (value === null) {
              return null
            }
            // Every row shows its series color, matching the legend, whichever mark the pointer is over.
            const indicatorColor = seriesColors[series] ?? point.color

            return (
              <div className="flex items-center gap-2.5" key={point.key}>
                {hideIndicator ? null : (
                  <span
                    aria-hidden
                    className={twMerge(
                      "shrink-0 border-current",
                      indicator === "dot" && "size-2.5 rounded-full",
                      indicator === "line" && "h-4 w-1 rounded-full",
                      indicator === "dashed" &&
                        "h-4 w-0 border-l-2 border-dashed bg-transparent"
                    )}
                    style={{
                      backgroundColor:
                        indicator === "dashed" ? "transparent" : indicatorColor,
                      borderColor: indicatorColor,
                    }}
                  />
                )}
                <span className="flex-1 text-muted-foreground">
                  {getLabel(config, series)}
                </span>
                <span className="font-mono font-medium text-foreground tabular-nums">
                  {valueFormatter(value)}
                </span>
              </div>
            )
          })}
      </div>
      {hintContent ? (
        <span className="mt-2.5 flex items-center gap-1 border-t border-border/70 pt-2 text-muted-foreground">
          {hintContent}
        </span>
      ) : null}
    </div>
  )
}

/** Value and caption centered over a donut or radial chart. */
function ChartCenterLabel({
  label,
  value,
}: {
  label?: ReactNode
  value: ReactNode
}) {
  return (
    <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
      <span className="text-xl font-semibold tracking-tight text-foreground tabular-nums">
        {value}
      </span>
      <span className="max-w-24 text-xs text-muted-foreground">{label}</span>
    </div>
  )
}

export type { ChartFrameContextValue, ChartFrameProps, ChartProps }

export {
  Chart,
  ChartCenterLabel,
  ChartFrame,
  ChartLegend,
  ChartTooltipContent,
  useChartFrame,
  useSeriesSelection,
}

export * from "./chart-core"

import type { ComponentType, HTMLAttributes, ReactNode } from "react"
import type {
  ChartAxisPresentationOptions,
  ChartCurve,
  ChartFocusMatch,
  ChartMarkState,
  ChartMotionContext,
  ChartPoint,
  ChartTooltipOptions,
  ChartValue,
} from "@tanstack/charts"
import { crosshair } from "@tanstack/charts/crosshair"
import { d3Curve } from "@tanstack/charts/d3/shape"
import { focusGroupX } from "@tanstack/charts/focus"
import type { ChartProps as TanStackChartProps } from "@tanstack/charts/react/tooltip"
import { scaleLinear } from "@tanstack/charts/scales/linear"
import {
  curveBasis,
  curveBumpX,
  curveLinear,
  curveMonotoneX,
  curveNatural,
  curveStep,
  curveStepAfter,
  curveStepBefore,
  type CurveFactory,
} from "d3-shape"
import type { ToggleButtonGroupProps } from "react-aria-components/ToggleButtonGroup"

type ChartType = "default" | "stacked" | "percent"
type ChartColor = (typeof CHART_COLORS)[number]
type ChartColorPalette = readonly [ChartColor, ...ChartColor[]]
type ChartDatum = Record<string, unknown>
type ChartCurveType = keyof typeof CURVES | ChartCurve

type ChartConfig = Record<
  string,
  {
    color?: ChartColor
    icon?: ComponentType<{ "data-slot"?: string }>
    label?: ReactNode
  }
>

type ChartAxisProps<TValue extends ChartValue = ChartValue> = {
  label?: string
  /** Tick label rotation in degrees; negative values tilt labels up to the left. */
  labelRotation?: number
  minTickGap?: number
  tickFormatter?: (value: TValue) => string
  tickMargin?: number
  ticks?: readonly TValue[]
  tickStrategy?: "all" | "auto" | "edges"
}

type ChartNumericAxisProps = ChartAxisProps<number> & {
  domain?: readonly [number, number]
}

type ChartTooltipProps = Pick<
  ChartTooltipOptions,
  "anchor" | "offset" | "placement"
> & {
  className?: string
  hideIndicator?: boolean
  hideLabel?: boolean
  indicator?: "line" | "dot" | "dashed"
  labelFormatter?: (label: ReactNode) => ReactNode
  labelSeparator?: boolean
  /** Muted line under the values, e.g. what clicking the hovered category does. Nothing renders when it returns null. */
  hint?: (category: string) => ReactNode
}

type ChartLegendProps = Omit<
  ToggleButtonGroupProps,
  | "children"
  | "className"
  | "onSelectionChange"
  | "selectedKeys"
  | "selectionMode"
> & {
  align?: "left" | "center" | "right"
  className?: string
  hideIcon?: boolean
  verticalAlign?: "top" | "bottom"
}

type ChartSizeProps = Pick<
  TanStackChartProps,
  "aspectRatio" | "height" | "initialWidth"
>

type TooltipDatum = {
  category: ChartValue
  series: string
  source: unknown
  value: number | null
}

type ChartTooltipContentProps<
  TDatum extends TooltipDatum = TooltipDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = {
  /** Series of the hovered point. */
  activeSeries?: string
  config: ChartConfig
  points: readonly ChartPoint<TDatum, TXValue, TYValue>[]
  tooltipProps?: ChartTooltipProps
  valueFormatter: (value: number) => string
}

type ChartTooltipRenderer<
  TDatum extends TooltipDatum = TooltipDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = (props: ChartTooltipContentProps<TDatum, TXValue, TYValue>) => ReactNode

interface BaseChartProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  ariaLabel?: string
  children?: never
  colors?: ChartColorPalette
  config: ChartConfig
  data: ChartDatum[]
  dataKey: string
  legend?: ReactNode | false
  size?: ChartSizeProps
  tooltip?: ChartTooltipRenderer | false
  tooltipProps?: ChartTooltipProps
  valueFormatter?: (value: number) => string
}

type CartesianChartProps = BaseChartProps & {
  grid?: "hidden" | "visible"
  xAxis?: ChartAxisProps | false
  yAxis?: ChartNumericAxisProps | false
}

type SeriesDatum = TooltipDatum & {
  index: number
  source: ChartDatum
}

type NamedSeriesDatum = Omit<TooltipDatum, "value"> & {
  color: string
  index: number
  source: ChartDatum
  value: number
}

/** Mark id for invisible hover and click targets, such as the full-height bars behind a bar chart. */
const CHART_HIT_MARK_ID = "chart-hit-target"

const CHART_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
] as const

const CURVES = {
  basis: curveBasis,
  bump: curveBumpX,
  linear: curveLinear,
  monotone: curveMonotoneX,
  monotoneX: curveMonotoneX,
  natural: curveNatural,
  step: curveStep,
  stepAfter: curveStepAfter,
  stepBefore: curveStepBefore,
} satisfies Record<string, CurveFactory>

/**
 * Group-x focus where the series closest to the pointer becomes the primary
 * point, so the crosshair marker lands on the line you point at.
 *
 * The built-in `"group-x"` preset first picks the painted mark that contains
 * the pointer, and a filled area contains everything below its line, so a
 * line could only win with the pointer exactly on its stroke. TanStack skips
 * that step for any strategy other than its own object. Area points also sit
 * mid-fill rather than on the edge, so `ignoreMarkId` drops them and focus
 * uses the line points along each top edge.
 */
function focusNearestSeries(ignoreMarkId?: string) {
  const keep = <TPoint extends { markId: string }>(
    points: readonly TPoint[]
  ) =>
    ignoreMarkId
      ? points.filter((point) => point.markId !== ignoreMarkId)
      : points

  const strategy: typeof focusGroupX = {
    group: (points, context) => focusGroupX.group(keep(points), context),
    navigation: (points) => focusGroupX.navigation(keep(points)),
    resolve: (points, context) => focusGroupX.resolve(keep(points), context),
  }
  return strategy
}

function valueToPercent(value: number) {
  return `${(value * 100).toFixed(0)}%`
}

function defaultValueFormatter(value: number) {
  return String(value)
}

function isChartValue(value: unknown): value is ChartValue {
  return (
    typeof value === "string" ||
    typeof value === "number" ||
    value instanceof Date
  )
}

function dimColor(color: string, opacity: number) {
  return `color-mix(in srgb, ${color} ${opacity}%, transparent)`
}

function getSelectedSeriesColor({
  color,
  opacity,
  selectedSeries,
  series,
}: {
  color: string
  opacity: number
  selectedSeries: string | null
  series: string
}) {
  if (selectedSeries === null || selectedSeries === series) {
    return color
  }

  return dimColor(color, opacity)
}

function getPositiveMaximum(values: readonly number[], maximum?: number) {
  const resolvedMaximum = maximum ?? Math.max(...values, 1)
  return Number.isFinite(resolvedMaximum) && resolvedMaximum > 0
    ? resolvedMaximum
    : 1
}

function getChartColors(
  config: ChartConfig,
  colors: ChartColorPalette = CHART_COLORS
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(config).map(([series, item], index) => [
      series,
      item.color ?? colors[index % colors.length] ?? colors[0],
    ])
  )
}

/** Color scale and theme shared by every chart. */
function getChartOptions(colorsBySeries: Record<string, string>) {
  const domain = Object.keys(colorsBySeries)
  const range = Object.values(colorsBySeries)

  return {
    color: { domain, range },
    theme: {
      background: "transparent",
      foreground: "var(--muted-foreground)",
      grid: "var(--muted)",
      muted: "color-mix(in srgb, var(--muted-foreground) 78%, transparent)",
      palette: range,
    },
  }
}

/**
 * Skips the renderer's grow-from-baseline entrance for a mark, so `Chart` can
 * reveal it left to right instead (`entrance="reveal"`). Updates still morph.
 */
function revealEntranceMotion(context: ChartMotionContext) {
  return context.phase === "enter" ? false : undefined
}

/** Fades every mark that does not match the current focus. */
function getFocusStates<TDatum>(
  match: ChartFocusMatch,
  opacity = 0.6
): ChartMarkState<TDatum>[] {
  return [
    {
      when: (context) => !context.matches(match),
      style: { opacity },
      transition: { type: "tween", duration: 150 },
    },
  ]
}

function getCrosshair() {
  return crosshair({
    // Snap with the tooltip instead of gliding behind the pointer.
    motion: false,
    marker: {
      fill: "var(--background)",
      radius: 4,
      stroke: "var(--foreground)",
      strokeOpacity: 0.7,
      strokeWidth: 2,
    },
    x: {
      stroke: "var(--muted-foreground)",
      strokeDasharray: "3 4",
      strokeOpacity: 0.3,
    },
    y: false,
  })
}

function toSeriesData({
  config,
  connectNulls = false,
  data,
  dataKey,
}: {
  config: ChartConfig
  connectNulls?: boolean
  data: ChartDatum[]
  dataKey: string
}) {
  const seriesNames = Object.keys(config)

  return data.flatMap((source, index) => {
    const category = source[dataKey]
    if (!isChartValue(category)) {
      return []
    }

    return seriesNames.flatMap((series) => {
      const rawValue = source[series]
      const value =
        typeof rawValue === "number" && Number.isFinite(rawValue)
          ? rawValue
          : null

      if (connectNulls && value === null) {
        return []
      }

      return [
        {
          category,
          index,
          series,
          source,
          value,
        } satisfies SeriesDatum,
      ]
    })
  })
}

function toNamedSeriesData({
  colors = CHART_COLORS,
  config,
  data,
  nameKey,
  selectedOpacity,
  selectedSeries,
  valueKey,
}: {
  colors?: ChartColorPalette
  config: ChartConfig
  data: ChartDatum[]
  nameKey: string
  selectedOpacity: number
  selectedSeries: string | null
  valueKey: string
}) {
  const chartColors = getChartColors(config, colors)

  return data.flatMap((source, index) => {
    const rawName = source[nameKey]
    const rawValue = source[valueKey]
    if (
      (typeof rawName !== "string" && typeof rawName !== "number") ||
      typeof rawValue !== "number" ||
      !Number.isFinite(rawValue)
    ) {
      return []
    }

    const series = String(rawName)
    const color =
      chartColors[series] ?? colors[index % colors.length] ?? colors[0]

    return [
      {
        category: series,
        color: getSelectedSeriesColor({
          color,
          opacity: selectedOpacity,
          selectedSeries,
          series,
        }),
        index,
        series,
        source,
        value: rawValue,
      } satisfies NamedSeriesDatum,
    ]
  })
}

/** Maps each named row to its (possibly dimmed) color for the chart color scale. */
function getNamedSeriesColors(rows: readonly NamedSeriesDatum[]) {
  return Object.fromEntries(rows.map((row) => [row.series, row.color]))
}

function getLabel(config: ChartConfig, series: string) {
  return config[series]?.label ?? series
}

function getTextLabel(config: ChartConfig, series: string) {
  const label = getLabel(config, series)
  return typeof label === "string" || typeof label === "number"
    ? String(label)
    : series
}

function getChartCurve(lineType: ChartCurveType = "linear") {
  return typeof lineType === "string" ? d3Curve(CURVES[lineType]) : lineType
}

function getAxis<TValue extends ChartValue>({
  edgeValues,
  format,
  props,
}: {
  edgeValues?: readonly TValue[]
  format?: (value: TValue) => string
  props?: ChartAxisProps<TValue> | false
}): ChartAxisPresentationOptions<TValue> | false {
  if (props === false) {
    return false
  }

  return {
    label: props?.label,
    line: false,
    tickLabels: {
      anchor: props?.labelRotation ? "end" : undefined,
      rotate: props?.labelRotation,
      fontSize: 11,
      fontWeight: 450,
      opacity: 0.78,
      thin:
        props?.tickStrategy === "all"
          ? false
          : { minGap: props?.minTickGap ?? 8, priority: "ends" },
    },
    ticks: {
      format: props?.tickFormatter ?? format,
      padding: props?.tickMargin ?? 9,
      size: 0,
      values: props?.tickStrategy === "edges" ? edgeValues : props?.ticks,
    },
  }
}

function getEdgeValues(data: ChartDatum[], dataKey: string) {
  const first = data.at(0)?.[dataKey]
  const last = data.at(-1)?.[dataKey]

  return isChartValue(first) && isChartValue(last) ? [first, last] : undefined
}

/** Scales and margin for a category axis paired with a numeric value axis. */
function getCartesianScales({
  categoryAxis,
  categoryScale,
  data,
  dataKey,
  grid,
  valueAxis,
  valueFormatter,
}: {
  categoryAxis?: ChartAxisProps | false
  categoryScale: () => unknown
  data: ChartDatum[]
  dataKey: string
  grid: "hidden" | "visible"
  valueAxis?: ChartNumericAxisProps | false
  valueFormatter: (value: number) => string
}) {
  const domain = valueAxis ? valueAxis.domain : undefined

  return {
    category: {
      axis: getAxis({
        edgeValues: getEdgeValues(data, dataKey),
        props: categoryAxis,
      }),
      scale: categoryScale,
    },
    value: {
      axis: getAxis({ format: valueFormatter, props: valueAxis }),
      grid: grid === "visible" ? { strokeDasharray: "3 3" } : false,
      // Without tick labels, rounding the domain only adds empty space.
      nice: valueAxis !== false,
      // A factory infers its domain from the data; only a configured instance keeps `domain`.
      scale: domain ? scaleLinear().domain(domain) : scaleLinear,
    },
    // With both axes hidden the chart is a sparkline: automatic margins would
    // still reserve guide space, so keep only room for strokes at the top and
    // bottom and let the plot run edge to edge.
    margin:
      categoryAxis === false && valueAxis === false
        ? { bottom: 3, left: 0, right: 0, top: 3 }
        : undefined,
  } as const
}

